@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"STAY_WORKER_ENABLED=false","RAIL_TICKET_WORKER_ENABLED=false","travbook.payments.refund-worker-enabled=false"})
@org.springframework.test.annotation.DirtiesContext(classMode=org.springframework.test.annotation.DirtiesContext.ClassMode.AFTER_CLASS)
@Import(PassengerCancellationIntegrationTest.TimeConfig.class)
@Testcontainers
class PassengerCancellationIntegrationTest {
 static final TestIssuer issuer=new TestIssuer();@Container static PostgreSQLContainer postgres=new PostgreSQLContainer("postgres:17.6-alpine");
 @DynamicPropertySource static void database(DynamicPropertyRegistry r){r.add("spring.datasource.url",postgres::getJdbcUrl);r.add("spring.datasource.username",postgres::getUsername);r.add("spring.datasource.password",postgres::getPassword);r.add("travbook.oidc-issuer",issuer::url);r.add("travbook.local-identity",()->true);}
 @TestConfiguration static class TimeConfig{@Bean @Primary MutableClock testClock(){return new MutableClock();}}
 static class MutableClock extends Clock{volatile Instant now=Instant.now();public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId zone){return Clock.fixed(now,zone);}public Instant instant(){return now;}}
 @Autowired MutableClock clock;@Autowired RailTickets tickets;@Autowired DiscoverTrains trains;@Autowired Customers customers;@Autowired ProcessRailTickets worker;@Autowired RailTicketStore store;@Autowired RailTicketSelection selections;@Autowired RailTicketEffects effects;@Autowired RailReservations supplier;@Autowired PaymentRefunds refunds;@Autowired com.travbook.payments.application.port.in.PaymentOperations payments;@Autowired JdbcClient jdbc;@Autowired ObjectMapper json;@LocalServerPort int port;
 @TempDir Path temp;static final AtomicInteger day=new AtomicInteger(5);CustomerIdentity identity;UUID owner;String token;final HttpClient http=HttpClient.newHttpClient();
 @BeforeEach void reset()throws Exception{clock.now=Instant.now();identity=new CustomerIdentity(issuer.url(),"rail-ticket-"+UUID.randomUUID());owner=customers.resolve(identity).id();token=issuer.token(identity.subject(),"bookings:read bookings:write");}
 @AfterAll static void closeIssuer(){issuer.close();}
 String key(){return UUID.randomUUID().toString();}UUID correlation(){return UUID.randomUUID();}
 RailTickets.QuoteDetails quote(){return quote(Rail.TravelClass.SL,1);}
 RailTickets.QuoteDetails quote(Rail.TravelClass type,int count){var date=LocalDate.now(ZoneId.of("Asia/Kolkata")).plusDays(day.incrementAndGet());return quoteAt(date,type,count);}
 RailTickets.QuoteDetails quoteAt(LocalDate date,Rail.TravelClass type,int count){var p=trains.search(new Rail.Criteria("NDLS","MMCT",date,Rail.Quota.GENERAL));var j=p.items().stream().filter(v->v.departure().getHour()==8).findFirst().orElseThrow();return tickets.quote(identity,j.id(),type,Rail.Quota.GENERAL,"NDLS",people(count),key(),correlation());}
 List<Passenger> people(int count){return java.util.stream.IntStream.range(0,count).mapToObj(i->new Passenger("Alex "+(char)('A'+i),"Example",LocalDate.parse("1990-01-01"),Berth.LOWER)).toList();}
 Booking book(RailTickets.QuoteDetails q,Scenario scenario){tickets.accept(identity,q.quote().id(),1,true,key(),correlation());return tickets.book(identity,q.quote().id(),1,scenario,true,key(),correlation());}
 void due(UUID id){jdbc.sql("update rail_ticket_work set next_at=clock_timestamp()-interval '1 second',lease_until=null where booking_id=:id and state in('READY','RUNNING')").param("id",id).update();}
 Booking finish(UUID id){for(int i=0;i<30;i++){var b=tickets.get(identity,id);if(b.terminal())return b;due(id);worker.tick();refunds.settleNext();}throw new AssertionError("Workflow did not finish");}
 int count(String table,String column,UUID id){return jdbc.sql("select count(*) from "+table+" where "+column+"=:id").param("id",id).query(Integer.class).single();}
 HttpResponse<String> call(String method,String path,String auth,String key,Object body)throws Exception{var r=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+path)).timeout(Duration.ofSeconds(10));if(auth!=null)r.header("Authorization","Bearer "+auth);if(key!=null)r.header("Idempotency-Key",key);if(method.equals("POST"))r.header("Content-Type","application/json").POST(body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body)));else r.GET();return http.send(r.build(),HttpResponse.BodyHandlers.ofString());}

 Booking issued(int count){return finish(book(quote(Rail.TravelClass.SL,count),Scenario.SUCCESS).id());}
 Booking cancelPart(Booking b,List<Integer> indexes,boolean loss){var q=tickets.passengerCancellationQuote(identity,b.id(),indexes,key(),correlation());tickets.cancelPassengers(identity,b.id(),q.id(),true,false,loss,key(),correlation());return finish(b.id());}
 @Test void successiveSelectionsReleaseOnlyTheirSeatsAndNeverOverRefund()throws Exception{var b=issued(3);var original=tickets.passengerVoucher(identity,b.id(),key(),correlation());assertThat(original.revision()).isZero();var q=tickets.passengerCancellationQuote(identity,b.id(),List.of(1),key(),correlation());assertThat(q.refundAmount().amount()).isEqualByComparingTo(b.quote().selection().availability().base().amount());String command=key();tickets.cancelPassengers(identity,b.id(),q.id(),true,false,true,command,correlation());assertThatThrownBy(()->tickets.readPassengerVoucher(identity,b.id(),0)).isInstanceOf(DomainFailure.class);var first=finish(b.id());assertThat(first.status()).isEqualTo(Status.ISSUED);assertThat(first.reservation()).isEqualTo(Reservation.RAC);assertThat(first.cancelledPassengerIndexes()).containsExactly(1);assertThat(first.activePassengers()).containsExactly(0,2);assertThat(tickets.cancelPassengers(identity,b.id(),q.id(),true,false,true,command,correlation()).id()).isEqualTo(b.id());assertThat(count("rail_provider_passenger_operation","reservation_id",b.id())).isEqualTo(1);assertThat(jdbc.sql("select quantity from rail_provider_reservation where id=:id").param("id",b.id()).query(Integer.class).single()).isEqualTo(2);
  assertThatThrownBy(()->tickets.passengerCancellationQuote(identity,b.id(),List.of(1),key(),correlation())).isInstanceOf(DomainFailure.class);assertThat(call("GET","/api/v1/rail-ticket-bookings/"+b.id(),token,null,null).statusCode()).isEqualTo(409);assertThat(call("GET","/api/v1/rail-ticket-pnr/"+b.supplierReference(),token,null,null).statusCode()).isEqualTo(409);
  var revised=tickets.passengerVoucher(identity,b.id(),key(),correlation());assertThat(revised.revision()).isEqualTo(1);assertThat(revised.content()).contains("CANCELLED — Passenger: Alex B Example","ACTIVE — Passenger: Alex A Example").doesNotContain("1990-01-01");assertThatThrownBy(()->tickets.readPassengerVoucher(identity,b.id(),0)).isInstanceOf(DomainFailure.class);assertThat(tickets.readPassengerVoucher(identity,b.id(),1).sha256()).isEqualTo(revised.sha256());
  var done=cancelPart(first,List.of(0,2),true);assertThat(done.status()).isEqualTo(Status.CANCELLED);assertThat(done.cancelledPassengerIndexes()).containsExactly(0,1,2);assertThat(tickets.cancellations(identity,b.id())).hasSize(2);assertThat(count("payment_refund","payment_id",b.id())).isEqualTo(2);assertThat(count("rail_provider_passenger_operation","reservation_id",b.id())).isEqualTo(2);assertThat(jdbc.sql("select sum(amount) from payment_refund where payment_id=:id").param("id",b.id()).query(java.math.BigDecimal.class).single()).isEqualByComparingTo(b.quote().selection().availability().base().amount().multiply(java.math.BigDecimal.valueOf(3)));assertThat(jdbc.sql("select count(*) from rail_provider_passenger where reservation_id=:id and active").param("id",b.id()).query(Integer.class).single()).isZero();assertThatThrownBy(()->tickets.readPassengerVoucher(identity,b.id(),3)).isInstanceOf(DomainFailure.class);
 }
 @Test void remainingChildCannotLoseTheOnlyAdultAndSelectionsAreValidated(){var seed=quote();var j=seed.quote().selection().journey();var passengers=List.of(people(1).getFirst(),new Passenger("Child","Example",j.departure().toLocalDate().minusYears(10),Berth.NONE));var q=tickets.quote(identity,j.id(),Rail.TravelClass.SL,Rail.Quota.GENERAL,"NDLS",passengers,key(),correlation());var b=finish(book(q,Scenario.SUCCESS).id());for(var indexes:List.of(List.of(0),List.of(-1),List.of(2),List.of(Integer.MAX_VALUE),List.of(1,1))){assertThatThrownBy(()->tickets.passengerCancellationQuote(identity,b.id(),indexes,key(),correlation())).isInstanceOf(DomainFailure.class);}assertThat(tickets.passengerCancellationQuote(identity,b.id(),List.of(1),key(),correlation()).passengerIndexes()).containsExactly(1);assertThat(cancelPart(b,List.of(0,1),false).status()).isEqualTo(Status.CANCELLED);}
 @Test void staleConcurrentQuotesAllowOnlyOneAftercareCycle()throws Exception{var b=issued(3);var q1=tickets.passengerCancellationQuote(identity,b.id(),List.of(0),key(),correlation());var q2=tickets.passengerCancellationQuote(identity,b.id(),List.of(1),key(),correlation());try(var pool=Executors.newFixedThreadPool(2)){var responses=pool.invokeAll(List.<Callable<Boolean>>of(()->attempt(b,q1),()->attempt(b,q2)));assertThat(responses.stream().filter(f->{try{return f.get();}catch(Exception e){throw new RuntimeException(e);}}).count()).isEqualTo(1);}var done=finish(b.id());assertThat(done.cancelledPassengerIndexes()).hasSize(1);assertThat(count("payment_refund","payment_id",b.id())).isEqualTo(1);assertThat(count("rail_provider_passenger_operation","reservation_id",b.id())).isEqualTo(1);}
 boolean attempt(Booking b,CancellationQuote q){try{tickets.cancelPassengers(identity,b.id(),q.id(),true,false,false,key(),correlation());return true;}catch(DomainFailure conflict){assertThat(conflict.code()).isEqualTo(DomainFailure.Code.BOOKING_CONFLICT);return false;}}
 @Test void ownershipLegacyMutationAndDelayedRefundGatesRemainEnforced()throws Exception{var b=issued(2);assertThat(call("POST","/api/v2/rail-ticket-bookings/"+b.id()+"/cancellation-quotes",token,key(),Map.of("passengerIndexes",List.of(0.5))).statusCode()).isEqualTo(400);assertThat(call("POST","/api/v2/rail-ticket-bookings/"+b.id()+"/cancellation-quotes",token,key(),Map.of("passengerIndexes",List.of(new java.math.BigDecimal("1.0")))).statusCode()).isEqualTo(201);var q=tickets.passengerCancellationQuote(identity,b.id(),List.of(1),key(),correlation());assertThat(call("POST","/api/v1/rail-ticket-bookings/"+b.id()+"/cancellations",token,key(),Map.of("cancellationQuoteId",q.id(),"consent",true,"simulateDelay",false,"simulateResponseLoss",false)).statusCode()).isEqualTo(409);String bob=issuer.token("other-"+key(),"bookings:read bookings:write");assertThat(call("GET","/api/v2/rail-ticket-bookings/"+b.id(),bob,null,null).statusCode()).isEqualTo(404);assertThat(call("POST","/api/v2/rail-ticket-bookings/"+b.id()+"/cancellation-quotes",bob,key(),Map.of("passengerIndexes",List.of(0))).statusCode()).isEqualTo(404);
  tickets.cancelPassengers(identity,b.id(),q.id(),true,true,false,key(),correlation());worker.tick();worker.tick();var pending=tickets.get(identity,b.id());assertThat(pending.status()).isEqualTo(Status.ISSUED);assertThat(pending.refund()).isEqualTo(Refund.PENDING);assertThatThrownBy(()->tickets.passengerCancellationQuote(identity,b.id(),List.of(0),key(),correlation())).isInstanceOf(DomainFailure.class);clock.now=clock.now.plusSeconds(6);refunds.settleNext();assertThat(finish(b.id()).refund()).isEqualTo(Refund.SUCCEEDED);
 }
 @Test void realProcessLossAfterPartialCancellationAndRefundCommitDoesNotRepeatEffects()throws Exception{for(String phase:List.of("CANCEL","REFUND")){var b=issued(2);var q=tickets.passengerCancellationQuote(identity,b.id(),List.of(1),key(),correlation());tickets.cancelPassengers(identity,b.id(),q.id(),true,false,false,key(),correlation());if(phase.equals("REFUND"))worker.tick();assertThat(child(phase)).isEqualTo(29);due(b.id());assertThat(child("RESUME")).isZero();var done=finish(b.id());assertThat(done.status()).isEqualTo(Status.ISSUED);assertThat(done.activePassengers()).containsExactly(0);assertThat(count("rail_provider_passenger_operation","reservation_id",b.id())).isEqualTo(1);assertThat(count("payment_refund","payment_id",b.id())).isEqualTo(1);assertThat(count("payment_refund_journal","operation_id",done.operation(Step.REFUND))).isEqualTo(2);}}
 @Test void legacyPendingRefundPayloadWithoutPassengerFieldsStillCompletes(){var b=issued(2);var q=tickets.cancellationQuote(identity,b.id(),key(),correlation());tickets.cancel(identity,b.id(),q.id(),true,false,false,key(),correlation());worker.tick();var pending=tickets.get(identity,b.id());var tree=(tools.jackson.databind.node.ObjectNode)json.valueToTree(pending);tree.remove("cancelledPassengerIndexes");((tools.jackson.databind.node.ObjectNode)tree.get("cancellation").get("quote")).remove("passengerIndexes");var restored=new com.travbook.railtickets.adapter.out.persistence.RailRecordReader(json).booking(tree.toString());assertThat(restored.cancelledPassengerIndexes()).containsExactly(0,1);assertThat(restored.refundSubmitted("MOCK-REFUND-legacy",true,clock.instant()).status()).isEqualTo(Status.CANCELLED);assertThat(finish(b.id()).status()).isEqualTo(Status.CANCELLED);}
 int child(String phase)throws Exception{Path log=temp.resolve(phase+".log");String cp=System.getProperty("surefire.test.class.path",System.getProperty("java.class.path"));var builder=new ProcessBuilder(Path.of(System.getProperty("java.home"),"bin","java").toString(),"-cp",cp,"com.travbook.support.RailTicketProcess",phase).redirectErrorStream(true).redirectOutput(log.toFile());builder.environment().put("DATABASE_URL",postgres.getJdbcUrl());builder.environment().put("DATABASE_USERNAME",postgres.getUsername());builder.environment().put("DATABASE_PASSWORD",postgres.getPassword());var process=builder.start();boolean done=process.waitFor(30,TimeUnit.SECONDS);if(!done)process.destroyForcibly();assertThat(done).isTrue();int code=process.exitValue();if(code!=0&&code!=29)throw new AssertionError(Files.readString(log));return code;}
}
